1	package com.example.starter.incident;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.time.Clock;
7	import java.time.Instant;
8	import java.time.temporal.ChronoUnit;
9	import java.util.HexFormat;
10	import java.util.List;
11	import java.util.Map;
12	import java.util.function.Supplier;
13	
14	import com.example.starter.incident.dto.Requests.ActionRequest;
15	import com.example.starter.incident.dto.Requests.EscalationAckRequest;
16	import com.example.starter.incident.dto.Requests.EscalationCheckRequest;
17	import com.example.starter.incident.dto.Requests.ReportRequest;
18	import com.example.starter.incident.dto.Requests.StatusRequest;
19	import com.example.starter.incident.dto.Requests.TakeoverRequest;
20	import com.example.starter.incident.dto.Requests.TransferAcceptRequest;
21	import com.example.starter.incident.dto.Requests.TransferRequest;
22	import com.example.starter.incident.dto.Responses.ActionView;
23	import com.example.starter.incident.dto.Responses.EscalationHistoryView;
24	import com.example.starter.incident.dto.Responses.EscalationView;
25	import com.example.starter.incident.dto.Responses.HistoryView;
26	import com.example.starter.incident.dto.Responses.IncidentView;
27	import com.example.starter.incident.dto.Responses.StatusChangeView;
28	import com.example.starter.incident.dto.Responses.TransferView;
29	import com.fasterxml.jackson.core.JsonProcessingException;
30	import com.fasterxml.jackson.databind.ObjectMapper;
31	import org.springframework.dao.DuplicateKeyException;
32	import org.springframework.stereotype.Service;
33	import org.springframework.transaction.annotation.Transactional;
34	
35	/**
36	 * 事件指挥核心服务。
37	 * 并发约定：所有写接口先 SELECT ... FOR UPDATE 锁定事件行，同事务内完成
38	 * 幂等键占位、业务校验与写入，保证并发请求按事务提交顺序生效。
39	 * 幂等约定：commandKey 全局唯一，同键同参重放首次响应，同键改参返回 409。
40	 * 遏制期限：首次进入 COMMANDING 时以该次接管 UTC 时刻按等级确定
41	 * （S1=5分钟、S2=15分钟、S3=60分钟、S4=240分钟），交接不重置。
42	 */
43	@Service
44	public class IncidentService {
45	
46	    private static final String SEP = "\\u001F";
47	
48	    /** 各严重等级的遏制时限（分钟），等级沿用上报值且不可修改。 */
49	    private static final Map<String, Long> CONTAINMENT_MINUTES = Map.of(
50	            "S1", 5L, "S2", 15L, "S3", 60L, "S4", 240L);
51	
52	    private final IncidentRepository incidents;
53	    private final EscalationRepository escalations;
54	    private final CommandKeyRepository commandKeys;
55	    private final ObjectMapper objectMapper;
56	    private final Clock clock;
57	
58	    public IncidentService(IncidentRepository incidents, EscalationRepository escalations,
59	                           CommandKeyRepository commandKeys, ObjectMapper objectMapper, Clock clock) {
60	        this.incidents = incidents;
61	        this.escalations = escalations;
62	        this.commandKeys = commandKeys;
63	        this.objectMapper = objectMapper;
64	        this.clock = clock;
65	    }
66	
67	    private Instant now() {
68	        return clock.instant();
69	    }
70	
71	    /**
72	     * 事件上报：初始状态 REPORTED，无指挥人。incidentKey 重复返回 409。
73	     */
74	    @Transactional
75	    public IncidentView report(ReportRequest req) {
76	        String incidentKey = requireText(req.incidentKey(), "incidentKey");
77	        String severity = requireText(req.severity(), "severity");
78	        if (!severity.matches("S[1-4]")) {
79	            throw ApiException.badRequest("severity 必须为 S1~S4");
80	        }
81	        String summary = requireText(req.summary(), "summary");
82	        String reporter = requireText(req.reporter(), "reporter");
83	        if (incidents.findByKey(incidentKey).isPresent()) {
84	            throw ApiException.conflict("incidentKey 已存在: " + incidentKey);
85	        }
86	        Instant now = now();
87	        Incident incident = new Incident(0L, incidentKey, severity, summary, reporter,
88	                IncidentStatus.REPORTED, null, now, now, null);
89	        long id;
90	        try {
91	            id = incidents.insert(incident);
92	        } catch (DuplicateKeyException e) {
93	            throw ApiException.conflict("incidentKey 已存在: " + incidentKey);
94	        }
95	        incidents.insertStatusChange(new StatusChange(0L, id, null, IncidentStatus.REPORTED, reporter, now));
96	        return toView(incidents.findByKey(incidentKey).orElseThrow(), null);
97	    }
98	
99	    /**
100	     * 首次接管：REPORTED → COMMANDING，记录当前指挥人，
101	     * 并以该次接管 UTC 时刻按等级确定遏制期限（只写一次，交接不重置）。
102	     */
103	    @Transactional
104	    public IncidentView takeover(String incidentKey, String actor, TakeoverRequest req) {
105	        String commandKey = requireText(req.commandKey(), "commandKey");
106	        Incident incident = lockIncident(incidentKey);
107	        return runIdempotent(commandKey, "takeover", hash(incidentKey, actor), IncidentView.class,
108	                () -> {
109	                    if (incident.status() != IncidentStatus.REPORTED) {
110	                        throw ApiException.illegalTransition(
111	                                "仅 REPORTED 状态可接管，当前状态: " + incident.status());
112	                    }
113	                    Instant now = now();
114	                    Instant deadline = now.plus(CONTAINMENT_MINUTES.get(incident.severity()),
115	                            ChronoUnit.MINUTES);
116	                    incidents.updateState(incident.id(), IncidentStatus.COMMANDING, actor, now);
117	                    incidents.updateDeadline(incident.id(), deadline, now);
118	                    incidents.insertStatusChange(new StatusChange(0L, incident.id(),
119	                            IncidentStatus.REPORTED, IncidentStatus.COMMANDING, actor, now));
120	                    return toView(incidents.findByKey(incidentKey).orElseThrow(), null);
121	                });
122	    }
123	
124	    /**
125	     * 发起交接：仅当前指挥人可发起，目标人必须不同；RESOLVED/CLOSED 禁止发起。
126	     */
127	    @Transactional
128	    public TransferView initiateTransfer(String incidentKey, String actor, TransferRequest req) {
129	        String commandKey = requireText(req.commandKey(), "commandKey");
130	        String toCommander = requireText(req.toCommander(), "toCommander");
131	        Incident incident = lockIncident(incidentKey);
132	        return runIdempotent(commandKey, "transfer_initiate", hash(incidentKey, actor, toCommander),
133	                TransferView.class, () -> {
134	                    requireCommander(incident, actor);
135	                    if (incident.status() == IncidentStatus.RESOLVED
136	                            || incident.status() == IncidentStatus.CLOSED) {
137	                        throw ApiException.illegalTransition(
138	                                incident.status() + " 状态不允许发起交接");
139	                    }
140	                    if (incident.status() == IncidentStatus.REPORTED) {
141	                        throw ApiException.illegalTransition("尚未接管的事件不能发起交接");
142	                    }
143	                    if (toCommander.equals(incident.commander())) {
144	                        throw ApiException.badRequest("目标指挥人必须与当前指挥人不同");
145	                    }
146	                    if (incidents.findPendingTransfer(incident.id()).isPresent()) {
147	                        throw ApiException.conflict("已存在待接受的交接，不能重复发起");
148	                    }
149	                    Instant now = now();
150	                    incidents.insertTransfer(new IncidentTransfer(0L, incident.id(),
151	                            incident.commander(), toCommander, TransferStatus.PENDING, now, null));
152	                    return toTransferView(incidents.findPendingTransfer(incident.id()).orElseThrow());
153	                });
154	    }
155	
156	    /**
157	     * 接受交接：仅待接受目标人可接受；接受后原子切换当前指挥人。
158	     * RESOLVED/CLOSED 禁止接受；待接受期间目标人无其他操作权限。
159	     */
160	    @Transactional
161	    public IncidentView acceptTransfer(String incidentKey, String actor, TransferAcceptRequest req) {
162	        String commandKey = requireText(req.commandKey(), "commandKey");
163	        Incident incident = lockIncident(incidentKey);
164	        return runIdempotent(commandKey, "transfer_accept", hash(incidentKey, actor), IncidentView.class,
165	                () -> {
166	                    if (incident.status() == IncidentStatus.RESOLVED
167	                            || incident.status() == IncidentStatus.CLOSED) {
168	                        throw ApiException.illegalTransition(
169	                                incident.status() + " 状态不允许接受交接");
170	                    }
171	                    IncidentTransfer pending = incidents.findPendingTransfer(incident.id())
172	                            .orElseThrow(() -> ApiException.conflict("当前没有待接受的交接"));
173	                    if (!pending.toCommander().equals(actor)) {
174	                        throw ApiException.conflict("只有交接目标人 " + pending.toCommander() + " 能接受交接");
175	                    }
176	                    Instant now = now();
177	                    incidents.acceptTransfer(pending.id(), now);
178	                    incidents.updateState(incident.id(), incident.status(), pending.toCommander(), now);
179	                    return toView(incidents.findByKey(incidentKey).orElseThrow(), null);
180	                });
181	    }
182	
183	    /**
184	     * 追加处置记录：仅当前指挥人可写；CLOSED 后禁止写入。
185	     * actionKey 事件内唯一：同键同内容幂等返回首次记录，同键不同内容返回 409。
186	     */
187	    @Transactional
188	    public ActionView addAction(String incidentKey, String actor, ActionRequest req) {
189	        String commandKey = requireText(req.commandKey(), "commandKey");
190	        String actionKey = requireText(req.actionKey(), "actionKey");
191	        String actionType = requireText(req.actionType(), "actionType");
192	        String note = requireText(req.note(), "note");
193	        if (req.occurredAt() == null) {
194	            throw ApiException.badRequest("occurredAt 不能为空");
195	        }
196	        Instant occurredAt = req.occurredAt().truncatedTo(ChronoUnit.MICROS);
197	        Incident incident = lockIncident(incidentKey);
198	        return runIdempotent(commandKey, "action",
199	                hash(incidentKey, actor, actionKey, actionType, note, occurredAt.toString()),
200	                ActionView.class, () -> {
201	                    requireCommander(incident, actor);
202	                    if (incident.status() == IncidentStatus.CLOSED) {
203	                        throw ApiException.illegalTransition("事件已关闭，不能再追加处置记录");
204	                    }
205	                    var existing = incidents.findAction(incident.id(), actionKey);
206	                    if (existing.isPresent()) {
207	                        IncidentAction found = existing.get();
208	                        if (!found.sameContent(actionType, note, occurredAt)) {
209	                            throw ApiException.conflict("actionKey 已被不同内容使用: " + actionKey);
210	                        }
211	                        return toActionView(found);
212	                    }
213	                    Instant now = now();
214	                    incidents.insertAction(new IncidentAction(0L, incident.id(), actionKey, actionType,
215	                            note, occurredAt, actor, now));
216	                    return toActionView(incidents.findAction(incident.id(), actionKey).orElseThrow());
217	                });
218	    }
219	
220	    /**
221	     * 状态变更：仅当前指挥人可操作，仅允许 COMMANDING→CONTAINED→RESOLVED→CLOSED 逐级前进。
222	     * 进入 CONTAINED 时同事务将仍 OPEN 的逾期升级记录原子置为 CANCELLED，已确认记录保留。
223	     */
224	    @Transactional
225	    public IncidentView changeStatus(String incidentKey, String actor, StatusRequest req) {
226	        String commandKey = requireText(req.commandKey(), "commandKey");
227	        String target = requireText(req.targetStatus(), "targetStatus");
228	        IncidentStatus targetStatus;
229	        try {
230	            targetStatus = IncidentStatus.valueOf(target);
231	        } catch (IllegalArgumentException e) {
232	            throw ApiException.badRequest("未知目标状态: " + target);
233	        }
234	        Incident incident = lockIncident(incidentKey);
235	        return runIdempotent(commandKey, "status", hash(incidentKey, actor, target),
236	                IncidentView.class, () -> {
237	                    requireCommander(incident, actor);
238	                    IncidentStatus next = incident.status().next();
239	                    if (next == null || next != targetStatus) {
240	                        throw ApiException.illegalTransition(
241	                                "不允许从 " + incident.status() + " 流转到 " + targetStatus);
242	                    }
243	                    Instant now = now();
244	                    incidents.updateState(incident.id(), targetStatus, incident.commander(), now);
245	                    incidents.insertStatusChange(new StatusChange(0L, incident.id(),
246	                            incident.status(), targetStatus, actor, now));
247	                    if (targetStatus == IncidentStatus.CONTAINED) {
248	                        escalations.cancelOpenForIncident(incident.id(), now);
249	                    }
250	                    return toView(incidents.findByKey(incidentKey).orElseThrow(), null);
251	                });
252	    }
253	
254	    /**
255	     * 单事件遏制逾期检查：以注入 Clock 的当前时刻评估，不做定时扫描。
256	     * 仅当事件仍为 COMMANDING、尚无升级记录且当前时刻 ≥ 接管时确定的期限时，
257	     * 追加一条 OPEN 记录（保存期限、触发时刻、当时指挥人），每事件至多一条。
258	     * 期限前或其他状态不产生记录；同键重放首次结果（含期限前的无记录结果），
259	     * 失败不占键；需要重新评估必须更换 commandKey。
260	     */
261	    @Transactional
262	    public EscalationHistoryView checkEscalation(String incidentKey, EscalationCheckRequest req) {
263	        String commandKey = requireText(req.commandKey(), "commandKey");
264	        Incident incident = lockIncident(incidentKey);
265	        return runIdempotent(commandKey, "escalation_check", hash(incidentKey),
266	                EscalationHistoryView.class, () -> {
267	                    var existing = escalations.findByIncident(incident.id());
268	                    if (existing.isPresent()) {
269	                        return toEscalationHistory(incident, List.of(existing.get()));
270	                    }
271	                    Instant currentTime = now();
272	                    if (incident.status() == IncidentStatus.COMMANDING
273	                            && incident.deadlineAt() != null
274	                            && !currentTime.isBefore(incident.deadlineAt())) {
275	                        escalations.insert(new Escalation(0L, incident.id(), incident.deadlineAt(),
276	                                currentTime, incident.commander(), EscalationStatus.OPEN,
277	                                null, null, null, currentTime, currentTime));
278	                    }
279	                    return toEscalationHistory(incident,
280	                            escalations.listByIncident(incident.id()));
281	                });
282	    }
283	
284	    /**
285	     * 确认 OPEN 升级记录：仅操作当时的当前指挥人可确认（待接受期间目标人无确认权，
286	     * 交接接受后旧指挥人失去确认权），提交非空处置说明后进入 ACKNOWLEDGED，
287	     * 记录确认人与 UTC 时刻。已 CANCELLED/ACKNOWLEDGED 或不存在记录均为 409。
288	     */
289	    @Transactional
290	    public EscalationView acknowledgeEscalation(String incidentKey, String actor,
291	                                                EscalationAckRequest req) {
292	        String commandKey = requireText(req.commandKey(), "commandKey");
293	        String note = requireText(req.note(), "note");
294	        Incident incident = lockIncident(incidentKey);
295	        return runIdempotent(commandKey, "escalation_ack", hash(incidentKey, actor, note),
296	                EscalationView.class, () -> {
297	                    requireCommander(incident, actor);
298	                    Escalation escalation = escalations.findByIncident(incident.id())
299	                            .orElseThrow(() -> ApiException.conflict("当前没有可确认的升级记录"));
300	                    if (escalation.status() != EscalationStatus.OPEN) {
301	                        throw ApiException.conflict(
302	                                "升级记录状态为 " + escalation.status() + "，不能确认");
303	                    }
304	                    Instant ackedAt = now();
305	                    int updated = escalations.acknowledge(escalation.id(), note, actor, ackedAt);
306	                    if (updated == 0) {
307	                        throw ApiException.conflict("升级记录已被并发处理，不能确认");
308	                    }
309	                    return toEscalationView(
310	                            escalations.findByIncident(incident.id()).orElseThrow());
311	                });
312	    }
313	
314	    /**
315	     * 查询事件当前状态（含当前指挥人与待接受交接目标人）。只读，不隐式写入。
316	     */
317	    @Transactional(readOnly = true)
318	    public IncidentView get(String incidentKey) {
319	        Incident incident = incidents.findByKey(incidentKey)
320	                .orElseThrow(() -> ApiException.notFound("事件不存在: " + incidentKey));
321	        String pendingTo = incidents.findPendingTransfer(incident.id())
322	                .map(IncidentTransfer::toCommander).orElse(null);
323	        return toView(incident, pendingTo);
324	    }
325	
326	    /**
327	     * 查询遏制期限、当前升级及完整升级历史；只读，不隐式写入。
328	     */
329	    @Transactional(readOnly = true)
330	    public EscalationHistoryView escalationHistory(String incidentKey) {
331	        Incident incident = incidents.findByKey(incidentKey)
332	                .orElseThrow(() -> ApiException.notFound("事件不存在: " + incidentKey));
333	        return toEscalationHistory(incident, escalations.listByIncident(incident.id()));
334	    }
335	
336	    /**
337	     * 查询完整历史：事件本体、状态流转、处置记录、交接记录、升级记录。
338	     */
339	    @Transactional(readOnly = true)
340	    public HistoryView history(String incidentKey) {
341	        Incident incident = incidents.findByKey(incidentKey)
342	                .orElseThrow(() -> ApiException.notFound("事件不存在: " + incidentKey));
343	        String pendingTo = incidents.findPendingTransfer(incident.id())
344	                .map(IncidentTransfer::toCommander).orElse(null);
345	        List<StatusChangeView> statusHistory = incidents.listStatusHistory(incident.id()).stream()
346	                .map(s -> new StatusChangeView(
347	                        s.fromStatus() == null ? null : s.fromStatus().name(),
348	                        s.toStatus().name(), s.actor(), s.occurredAt()))
349	                .toList();
350	        List<ActionView> actions = incidents.listActions(incident.id()).stream()
351	                .map(this::toActionView).toList();
352	        List<TransferView> transfers = incidents.listTransfers(incident.id()).stream()
353	                .map(IncidentService::toTransferView).toList();
354	        List<EscalationView> escalationList = escalations.listByIncident(incident.id()).stream()
355	                .map(this::toEscalationView).toList();
356	        return new HistoryView(toView(incident, pendingTo), statusHistory, actions, transfers,
357	                escalationList);
358	    }
359	
360	    private Incident lockIncident(String incidentKey) {
361	        requireText(incidentKey, "incidentKey");
362	        return incidents.lockByKey(incidentKey)
363	                .orElseThrow(() -> ApiException.notFound("事件不存在: " + incidentKey));
364	    }
365	
366	    private static void requireCommander(Incident incident, String actor) {
367	        if (incident.commander() == null || !incident.commander().equals(actor)) {
368	            throw ApiException.conflict("只有当前指挥人 "
369	                    + (incident.commander() == null ? "(无)" : incident.commander()) + " 能执行该操作");
370	        }
371	    }
372	
373	    private static String requireText(String value, String field) {
374	        if (value == null || value.isBlank()) {
375	            throw ApiException.badRequest(field + " 不能为空");
376	        }
377	        return value.strip();
378	    }
379	
380	    /**
381	     * 幂等执行：同键同参重放首次响应，同键改参 409；并发同键由唯一约束串行化。
382	     */
383	    private <T> T runIdempotent(String commandKey, String operation, String requestHash,
384	                                Class<T> type, Supplier<T> business) {
385	        var existing = commandKeys.find(commandKey);
386	        if (existing.isPresent()) {
387	            return replay(existing.get(), operation, requestHash, type);
388	        }
389	        try {
390	            commandKeys.insertPlaceholder(commandKey, operation, requestHash, now());
391	        } catch (DuplicateKeyException e) {
392	            var committed = commandKeys.findForUpdate(commandKey)
393	                    .orElseThrow(() -> ApiException.conflict("commandKey 处理冲突: " + commandKey));
394	            return replay(committed, operation, requestHash, type);
395	        }
396	        T result = business.get();
397	        commandKeys.fillResponse(commandKey, 200, toJson(result));
398	        return result;
399	    }
400	
401	    private <T> T replay(CommandKeyRecord record, String operation, String requestHash, Class<T> type) {
402	        if (!record.operation().equals(operation) || !record.requestHash().equals(requestHash)) {
403	            throw ApiException.conflict("commandKey 已被不同参数的请求使用: " + record.commandKey());
404	        }
405	        if (record.responseBody() == null) {
406	            throw ApiException.conflict("commandKey 正在处理中: " + record.commandKey());
407	        }
408	        try {
409	            return objectMapper.readValue(record.responseBody(), type);
410	        } catch (JsonProcessingException e) {
411	            throw new IllegalStateException("幂等响应反序列化失败", e);
412	        }
413	    }
414	
415	    private String toJson(Object value) {
416	        try {
417	            return objectMapper.writeValueAsString(value);
418	        } catch (JsonProcessingException e) {
419	            throw new IllegalStateException("响应序列化失败", e);
420	        }
421	    }
422	
423	    private static String hash(String... parts) {
