1	package com.example.starter.incident;
2	
3	import java.sql.ResultSet;
4	import java.sql.SQLException;
5	import java.sql.Statement;
6	import java.sql.Timestamp;
7	import java.time.Instant;
8	import java.util.List;
9	import java.util.Optional;
10	
11	import org.springframework.jdbc.core.JdbcTemplate;
12	import org.springframework.jdbc.core.RowMapper;
13	import org.springframework.jdbc.support.GeneratedKeyHolder;
14	import org.springframework.jdbc.support.KeyHolder;
15	import org.springframework.stereotype.Repository;
16	
17	/**
18	 * 遏制逾期升级记录仓储。每个事件至多一条记录（uk_escalation_incident 唯一约束）。
19	 * 所有调用均处于先锁定事件行的写事务内，并发检查/确认/遏制按事务提交顺序串行化。
20	 */
21	@Repository
22	public class EscalationRepository {
23	
24	    private final JdbcTemplate jdbc;
25	
26	    public EscalationRepository(JdbcTemplate jdbc) {
27	        this.jdbc = jdbc;
28	    }
29	
30	    private static final RowMapper<Escalation> MAPPER = (rs, n) -> map(rs);
31	
32	    private static Escalation map(ResultSet rs) throws SQLException {
33	        Timestamp ackedAt = rs.getTimestamp("acknowledged_at");
34	        return new Escalation(
35	                rs.getLong("id"), rs.getLong("incident_id"),
36	                rs.getTimestamp("deadline_at").toInstant(),
37	                rs.getTimestamp("triggered_at").toInstant(),
38	                rs.getString("triggered_commander"),
39	                EscalationStatus.valueOf(rs.getString("status")),
40	                rs.getString("note"), rs.getString("acknowledged_by"),
41	                ackedAt == null ? null : ackedAt.toInstant(),
42	                rs.getTimestamp("created_at").toInstant(),
43	                rs.getTimestamp("updated_at").toInstant());
44	    }
45	
46	    /**
47	     * 插入 OPEN 升级记录，返回生成主键。每事件唯一约束兜底并发重复插入。
48	     */
49	    public long insert(Escalation escalation) {
50	        KeyHolder keys = new GeneratedKeyHolder();
51	        jdbc.update(con -> {
52	            var ps = con.prepareStatement(
53	                    "INSERT INTO incident_escalations (incident_id, deadline_at, triggered_at,"
54	                            + " triggered_commander, status, note, acknowledged_by, acknowledged_at,"
55	                            + " created_at, updated_at) VALUES (?,?,?,?,?,?,?,?,?,?)",
56	                    Statement.RETURN_GENERATED_KEYS);
57	            ps.setLong(1, escalation.incidentId());
58	            ps.setTimestamp(2, Timestamp.from(escalation.deadlineAt()));
59	            ps.setTimestamp(3, Timestamp.from(escalation.triggeredAt()));
60	            ps.setString(4, escalation.triggeredCommander());
61	            ps.setString(5, escalation.status().name());
62	            ps.setString(6, escalation.note());
63	            ps.setString(7, escalation.acknowledgedBy());
64	            ps.setTimestamp(8, escalation.acknowledgedAt() == null
65	                    ? null : Timestamp.from(escalation.acknowledgedAt()));
66	            ps.setTimestamp(9, Timestamp.from(escalation.createdAt()));
67	            ps.setTimestamp(10, Timestamp.from(escalation.updatedAt()));
68	            return ps;
69	        }, keys);
70	        return keys.getKey().longValue();
71	    }
72	
73	    /**
74	     * 查询事件的唯一升级记录（不存在返回空）。
75	     */
76	    public Optional<Escalation> findByIncident(long incidentId) {
77	        List<Escalation> rows = jdbc.query(
78	                "SELECT * FROM incident_escalations WHERE incident_id = ?", MAPPER, incidentId);
79	        return rows.stream().findFirst();
80	    }
81	
82	    /**
83	     * 将指定 OPEN 记录原子置为 ACKNOWLEDGED；条件包含 status='OPEN'，
84	     * 已被取消的记录更新行数为 0。
85	     */
86	    public int acknowledge(long id, String note, String acknowledgedBy, Instant acknowledgedAt) {
87	        return jdbc.update("UPDATE incident_escalations SET status = 'ACKNOWLEDGED', note = ?,"
88	                        + " acknowledged_by = ?, acknowledged_at = ?, updated_at = ?"
89	                        + " WHERE id = ? AND status = 'OPEN'",
90	                note, acknowledgedBy, Timestamp.from(acknowledgedAt), Timestamp.from(acknowledgedAt), id);
91	    }
92	
93	    /**
94	     * 遏制提交时将事件仍 OPEN 的记录原子置为 CANCELLED；已确认记录保留。
95	     * 返回被取消的记录数（0 或 1）。
96	     */
97	    public int cancelOpenForIncident(long incidentId, Instant cancelledAt) {
98	        return jdbc.update("UPDATE incident_escalations SET status = 'CANCELLED', updated_at = ?"
99	                        + " WHERE incident_id = ? AND status = 'OPEN'",
