211	    @Test
212	    void acknowledge_transferBoundaries() {
213	        setup("INC-E-020", "S1", "alice");
214	        ((ControllableClock) clock).setInstant(T0.plus(6, ChronoUnit.MINUTES));
215	        service.checkEscalation("INC-E-020", new EscalationCheckRequest(key()));
216	        service.initiateTransfer("INC-E-020", "alice", new TransferRequest(key(), "bob"));
217	        // 待接受期间目标人无确认权
218	        assertApiStatus(() -> service.acknowledgeEscalation("INC-E-020", "bob",
219	                new EscalationAckRequest(key(), "bob 说明")), HttpStatus.CONFLICT);
220	        // 旧指挥人待接受期间仍可确认
221	        EscalationView byAlice = service.acknowledgeEscalation("INC-E-020", "alice",
222	                new EscalationAckRequest(key(), "alice 说明"));
223	        assertThat(byAlice.status()).isEqualTo("ACKNOWLEDGED");
224	
225	        // 交接接受后旧指挥人失去确认权：另造一条 OPEN 走 bob 确认路径
226	        ((ControllableClock) clock).setInstant(T0.plus(30, ChronoUnit.MINUTES));
227	        setup("INC-E-021", "S1", "alice");
228	        ((ControllableClock) clock).setInstant(T0.plus(36, ChronoUnit.MINUTES));
229	        service.checkEscalation("INC-E-021", new EscalationCheckRequest(key()));
