1	package com.example.starter.incident;
2	
3	import java.sql.ResultSet;
4	import java.sql.SQLException;
5	import java.sql.Timestamp;
6	import java.time.Instant;
7	import java.util.List;
8	import java.util.Optional;
9	
10	import org.springframework.dao.DuplicateKeyException;
11	import org.springframework.jdbc.core.JdbcTemplate;
12	import org.springframework.jdbc.core.RowMapper;
13	import org.springframework.stereotype.Repository;
14	
15	/**
16	 * 命令幂等键仓储。command_key 全局唯一；
17	 * 先占位插入、同事务内补写响应，并发同键插入由唯一约束串行化。
18	 */
19	@Repository
20	public class CommandKeyRepository {
21	
22	    private final JdbcTemplate jdbc;
23	
24	    public CommandKeyRepository(JdbcTemplate jdbc) {
25	        this.jdbc = jdbc;
26	    }
27	
28	    private static final RowMapper<CommandKeyRecord> MAPPER = (rs, n) -> map(rs);
29	
30	    private static CommandKeyRecord map(ResultSet rs) throws SQLException {
31	        int status = rs.getInt("response_status");
32	        return new CommandKeyRecord(rs.getLong("id"), rs.getString("command_key"),
33	                rs.getString("operation"), rs.getString("request_hash"),
34	                rs.wasNull() ? null : status, rs.getString("response_body"),
35	                rs.getTimestamp("created_at").toInstant());
36	    }
37	
38	    /**
39	     * 按命令键查询（普通读）。
40	     */
41	    public Optional<CommandKeyRecord> find(String commandKey) {
42	        List<CommandKeyRecord> rows = jdbc.query("SELECT * FROM command_keys WHERE command_key = ?",
43	                MAPPER, commandKey);
44	        return rows.stream().findFirst();
45	    }
46	
47	    /**
48	     * 按命令键锁定读（SELECT ... FOR UPDATE），读取最新已提交数据，用于唯一冲突后的重查。
49	     */
50	    public Optional<CommandKeyRecord> findForUpdate(String commandKey) {
51	        List<CommandKeyRecord> rows = jdbc.query(
52	                "SELECT * FROM command_keys WHERE command_key = ? FOR UPDATE", MAPPER, commandKey);
53	        return rows.stream().findFirst();
54	    }
55	
56	    /**
57	     * 占位插入幂等键（响应列为空，同事务内随后补写）。
58	     *
59	     * @throws DuplicateKeyException 同键已存在（含并发事务已提交）时抛出
60	     */
61	    public void insertPlaceholder(String commandKey, String operation, String requestHash, Instant now) {
62	        jdbc.update("INSERT INTO command_keys (command_key, operation, request_hash, response_status,"
63	                + " response_body, created_at) VALUES (?,?,?,NULL,NULL,?)",
64	                commandKey, operation, requestHash, Timestamp.from(now));
65	    }
66	
67	    /**
68	     * 补写首次成功的响应，与业务写入同事务提交。
69	     */
