private long suspendedSeconds(List<Suspension> list, Instant now) {
    long total = 0;
    for (Suspension s : list) {
        Instant end = s.resumedAt() == null ? now : s.resumedAt();
        total += Duration.between(s.suspendedAt(), end).getSeconds(); // could use toMillis
    }
