package com.example.starter.incident;

import static org.assertj.core.api.Assertions.assertThat;

import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;
import java.util.concurrent.Callable;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;

import com.example.starter.incident.dto.Requests.ActionRequest;
import com.example.starter.incident.dto.Requests.ReportRequest;
import com.example.starter.incident.dto.Requests.StatusRequest;
import com.example.starter.incident.dto.Requests.TakeoverRequest;
import com.example.starter.incident.dto.Requests.TransferAcceptRequest;
import com.example.starter.incident.dto.Requests.TransferRequest;
import com.example.starter.incident.dto.Responses.IncidentView;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;

/**
 * 并发边界测试：验证行锁串行化与幂等键唯一约束下，
 * 并发接管、交接接受与状态推进按事务提交顺序生效，且同键重放安全。
 */
@SpringBootTest
class IncidentConcurrencyTest {

    @Autowired
    private IncidentService service;

    @Autowired
    private JdbcTemplate jdbc;

    @BeforeEach
    void clean() {
        jdbc.update("DELETE FROM command_keys");
        jdbc.update("DELETE FROM incident_status_history");
        jdbc.update("DELETE FROM incident_transfers");
        jdbc.update("DELETE FROM incident_actions");
        jdbc.update("DELETE FROM incidents");
    }

    private static String key() {
        return "INC-" + UUID.randomUUID();
    }

    /**
     * 并发提交一批任务并收集结果（成功值或异常）。
     */
    private static <T> List<Object> runConcurrently(List<Callable<T>> tasks) throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(tasks.size());
        try {
            CountDownLatch ready = new CountDownLatch(tasks.size());
            CountDownLatch start = new CountDownLatch(1);
            List<Future<Object>> futures = new ArrayList<>();
            for (Callable<T> task : tasks) {
                futures.add(pool.submit(() -> {
                    ready.countDown();
                    start.await(5, TimeUnit.SECONDS);
                    try {
                        return task.call();
                    } catch (Exception e) {
                        return e;
                    }
                }));
            }
            assertThat(ready.await(10, TimeUnit.SECONDS)).isTrue();
            start.countDown();
            List<Object> results = new ArrayList<>();
            for (Future<Object> future : futures) {
                results.add(future.get(30, TimeUnit.SECONDS));
            }
            return results;
        } finally {
            pool.shutdownNow();
        }
    }

    @Test
    void concurrentTakeover_exactlyOneWins() throws Exception {
        String ik = "INC-200";
        service.report(new ReportRequest(ik, "S1", "并发接管", "r"));
        List<Callable<IncidentView>> tasks = new ArrayList<>();
        for (int i = 0; i < 4; i++) {
            String actor = "actor-" + i;
            tasks.add(() -> service.takeover(ik, actor, new TakeoverRequest(key())));
        }
        List<Object> results = runConcurrently(tasks);
        long successes = results.stream().filter(IncidentView.class::isInstance).count();
        long illegal = results.stream().filter(ApiException.class::isInstance)
                .map(ApiException.class::cast)
                .filter(e -> e.status().value() == 422).count();
        assertThat(successes).isEqualTo(1);
        assertThat(illegal).isEqualTo(3);
        // 状态只流转一次
        assertThat(service.history(ik).statusHistory())
                .filteredOn(s -> "COMMANDING".equals(s.toStatus())).hasSize(1);
    }

    @Test
    void concurrentAcceptAndResolve_commitOrderWins() throws Exception {
        String ik = "INC-201";
        service.report(new ReportRequest(ik, "S1", "交接与解决并发", "r"));
        service.takeover(ik, "alice", new TakeoverRequest(key()));
        service.changeStatus(ik, "alice", new StatusRequest(key(), "CONTAINED"));
        service.initiateTransfer(ik, "alice", new TransferRequest(key(), "bob"));

        List<Object> results = runConcurrently(List.of(
                () -> service.acceptTransfer(ik, "bob", new TransferAcceptRequest(key())),
                () -> service.changeStatus(ik, "alice", new StatusRequest(key(), "RESOLVED"))));

        long successes = results.stream().filter(IncidentView.class::isInstance).count();
        long failures = results.stream().filter(ApiException.class::isInstance).count();
        assertThat(successes).isEqualTo(1);
        assertThat(failures).isEqualTo(1);

        IncidentView end = service.get(ik);
        var transfers = service.history(ik).transfers();
        if ("RESOLVED".equals(end.status())) {
            // 解决先提交：交接接受必须失败，指挥人不变
            assertThat(end.commander()).isEqualTo("alice");
            assertThat(transfers.get(0).status()).isEqualTo("PENDING");
        } else {
            // 接受先提交：旧指挥人的解决必须失败，状态仍 CONTAINED，指挥人已切换
            assertThat(end.status()).isEqualTo("CONTAINED");
            assertThat(end.commander()).isEqualTo("bob");
            assertThat(transfers.get(0).status()).isEqualTo("ACCEPTED");
        }
    }

    @Test
    void concurrentSameCommandKey_singleEffect() throws Exception {
        String ik = "INC-202";
        service.report(new ReportRequest(ik, "S1", "同键并发", "r"));
        String commandKey = key();
        List<Callable<IncidentView>> tasks = new ArrayList<>();
        for (int i = 0; i < 3; i++) {
            tasks.add(() -> service.takeover(ik, "alice", new TakeoverRequest(commandKey)));
        }
        List<Object> results = runConcurrently(tasks);

        List<IncidentView> successes = results.stream().filter(IncidentView.class::isInstance)
                .map(IncidentView.class::cast).toList();
        assertThat(successes).isNotEmpty();
        // 所有成功响应一致，且接管只生效一次
        assertThat(successes).allSatisfy(v -> assertThat(v).isEqualTo(successes.get(0)));
        assertThat(service.get(ik).commander()).isEqualTo("alice");
        assertThat(service.history(ik).statusHistory())
                .filteredOn(s -> "COMMANDING".equals(s.toStatus())).hasSize(1);
        Integer keyCount = jdbc.queryForObject(
                "SELECT COUNT(*) FROM command_keys WHERE command_key = ?", Integer.class, commandKey);
        assertThat(keyCount).isEqualTo(1);
    }

    @Test
    void concurrentActions_distinctKeysBothPersist() throws Exception {
        String ik = "INC-203";
        service.report(new ReportRequest(ik, "S3", "并发处置记录", "r"));
        service.takeover(ik, "alice", new TakeoverRequest(key()));
        List<Callable<Object>> tasks = new ArrayList<>();
        for (int i = 0; i < 4; i++) {
            String actionKey = "ACT-" + i;
            tasks.add(() -> service.addAction(ik, "alice", new ActionRequest(key(), actionKey,
                    "NOTE", "记录 " + actionKey, Instant.parse("2026-09-21T08:00:00Z"))));
        }
        List<Object> results = runConcurrently(tasks);
        assertThat(results).allSatisfy(r -> assertThat(r).isNotInstanceOf(Exception.class));
        assertThat(service.history(ik).actions()).hasSize(4);
    }
}

package com.example.starter.incident;

import static org.assertj.core.api.Assertions.assertThat;

import java.time.Clock;
import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;
import java.util.concurrent.Callable;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;

import com.example.starter.incident.dto.Requests.EscalationAckRequest;
import com.example.starter.incident.dto.Requests.EscalationCheckRequest;
import com.example.starter.incident.dto.Requests.ReportRequest;
import com.example.starter.incident.dto.Requests.StatusRequest;
import com.example.starter.incident.dto.Requests.TakeoverRequest;
import com.example.starter.incident.dto.Responses.EscalationView;
import com.example.starter.incident.dto.Responses.IncidentView;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.context.annotation.Import;
import org.springframework.jdbc.core.JdbcTemplate;

/**
 * 遏制逾期并发测试：验证检查、确认与遏制在事件行锁下按事务提交顺序生效——
 * 遏制先提交不再新增升级；确认与遏制竞争时升级状态不可回退，不能在取消后补确认。
 * 使用可控 Clock 将事件置于已逾期状态，不依赖真实睡眠。
 */
@SpringBootTest
@Import(ControllableClock.Config.class)
class EscalationConcurrencyTest {

    private static final Instant T0 = Instant.parse("2026-09-22T00:00:00Z");

    @Autowired
    private IncidentService service;

    @Autowired
    private JdbcTemplate jdbc;

    @Autowired
    private Clock clock;

    @BeforeEach
    void clean() {
        jdbc.update("DELETE FROM command_keys");
        jdbc.update("DELETE FROM incident_escalations");
        jdbc.update("DELETE FROM incident_status_history");
        jdbc.update("DELETE FROM incident_transfers");
        jdbc.update("DELETE FROM incident_actions");
        jdbc.update("DELETE FROM incidents");
        ((ControllableClock) clock).setInstant(T0);
    }

    private static String key() {
        return "CMD-" + UUID.randomUUID();
    }

    private void overdueCommanding(String incidentKey) {
        service.report(new ReportRequest(incidentKey, "S1", "并发逾期", "r"));
        service.takeover(incidentKey, "alice", new TakeoverRequest(key()));
        ((ControllableClock) clock).setInstant(T0.plus(10, ChronoUnit.MINUTES));
    }

    private static <T> List<Object> runConcurrently(List<Callable<T>> tasks) throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(tasks.size());
        try {
            CountDownLatch ready = new CountDownLatch(tasks.size());
            CountDownLatch start = new CountDownLatch(1);
            List<Future<Object>> futures = new ArrayList<>();
            for (Callable<T> task : tasks) {
                futures.add(pool.submit(() -> {
                    ready.countDown();
                    start.await(5, TimeUnit.SECONDS);
                    try {
                        return task.call();
                    } catch (Exception e) {
                        return e;
                    }
                }));
            }
            assertThat(ready.await(10, TimeUnit.SECONDS)).isTrue();
            start.countDown();
            List<Object> results = new ArrayList<>();
            for (Future<Object> future : futures) {
                results.add(future.get(30, TimeUnit.SECONDS));
            }
            return results;
        } finally {
            pool.shutdownNow();
        }
    }

    @Test
    void concurrentCheckAndContain_commitOrderWins_noOpenLingers() throws Exception {
        for (int round = 0; round < 5; round++) {
            String ik = "INC-C-" + round;
            overdueCommanding(ik);
            List<Object> results = runConcurrently(List.of(
                    () -> service.checkEscalation(ik, new EscalationCheckRequest(key())),
                    () -> service.changeStatus(ik, "alice", new StatusRequest(key(), "CONTAINED"))));
            long failures = results.stream().filter(ApiException.class::isInstance).count();
            // 两个操作语义上都可能成功（检查在非 COMMANDING 时是空结果成功），但结果必须自洽
            assertThat(failures).isZero();

            IncidentView end = service.get(ik);
            List<EscalationView> escalations = service.history(ik).escalations();
            if ("CONTAINED".equals(end.status()) && escalations.isEmpty()) {
                // 遏制先提交：检查不再新增升级
                continue;
            }
            // 检查先提交：恰好一条记录，且被同事务/随后的遏制取消，绝不残留 OPEN
            assertThat(end.status()).isEqualTo("CONTAINED");
            assertThat(escalations).hasSize(1);
            assertThat(escalations.get(0).status()).isEqualTo("CANCELLED");
        }
    }

    @Test
    void concurrentAcknowledgeAndContain_noRollbackOrLateAck() throws Exception {
        String ik = "INC-C-ACK";
        overdueCommanding(ik);
        // 先产生一条 OPEN 记录
        service.checkEscalation(ik, new EscalationCheckRequest(key()));

        List<Object> results = runConcurrently(List.of(
                () -> service.acknowledgeEscalation(ik, "alice",
                        new EscalationAckRequest(key(), "并发确认说明")),
                () -> service.changeStatus(ik, "alice", new StatusRequest(key(), "CONTAINED"))));

        long acks = results.stream().filter(r -> r instanceof EscalationView).count();
        long conflicts = results.stream().filter(ApiException.class::isInstance)
                .map(ApiException.class::cast).filter(e -> e.status().value() == 409).count();
        long views = results.stream().filter(IncidentView.class::isInstance).count();
        assertThat(views).isEqualTo(1);
        assertThat(acks + conflicts).isEqualTo(1);

        EscalationView end = service.escalationHistory(ik).current();
        if (acks == 1) {
            // 确认先提交：遏制保留已确认记录，状态不回退
            assertThat(end.status()).isEqualTo("ACKNOWLEDGED");
            assertThat(end.acknowledgedBy()).isEqualTo("alice");
            assertThat(end.note()).isEqualTo("并发确认说明");
        } else {
            // 遏制先提交：记录 CANCELLED，确认失败且之后不能补确认
            assertThat(end.status()).isEqualTo("CANCELLED");
            assertThat(conflicts).isEqualTo(1);
        }
        // 终态后再确认一律 409，状态绝不回退
        try {
            service.acknowledgeEscalation(ik, "alice",
                    new EscalationAckRequest(key(), "事后补确认"));
            throw new AssertionError("遏制后不应允许确认");
        } catch (ApiException e) {
            assertThat(e.status().value()).isEqualTo(409);
        }
        assertThat(service.escalationHistory(ik).current().status()).isEqualTo(end.status());
    }

    @Test
    void concurrentChecks_sameIncident_singleRecord() throws Exception {
        String ik = "INC-C-MULTI";
        overdueCommanding(ik);
        List<Callable<Object>> tasks = new ArrayList<>();
        for (int i = 0; i < 4; i++) {
            tasks.add(() -> service.checkEscalation(ik, new EscalationCheckRequest(key())));
        }
        List<Object> results = runConcurrently(tasks);
        assertThat(results).allSatisfy(r -> assertThat(r).isNotInstanceOf(Exception.class));
        assertThat(service.history(ik).escalations()).hasSize(1);
        assertThat(service.escalationHistory(ik).current().status()).isEqualTo("OPEN");
    }
}

package com.example.starter.incident;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import java.util.UUID;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.web.servlet.MockMvc;

/**
 * HTTP 层测试：验证路由、X-Actor-Id 请求头约束及 400/404/409/422 错误语义可区分。
 */
@SpringBootTest
@AutoConfigureMockMvc
class IncidentApiTest {

    @Autowired
    private MockMvc mvc;

    @Autowired
    private JdbcTemplate jdbc;

    @BeforeEach
    void clean() {
        jdbc.update("DELETE FROM command_keys");
        jdbc.update("DELETE FROM incident_status_history");
        jdbc.update("DELETE FROM incident_transfers");
        jdbc.update("DELETE FROM incident_actions");
        jdbc.update("DELETE FROM incidents");
    }

    private static String key() {
        return "INC-" + UUID.randomUUID();
    }

    private void report(String incidentKey) throws Exception {
        mvc.perform(post("/api/incidents")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"incidentKey\":\"" + incidentKey
                                + "\",\"severity\":\"S1\",\"summary\":\"s\",\"reporter\":\"r\"}"))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.status").value("REPORTED"));
    }

    private void takeover(String incidentKey, String actor) throws Exception {
        mvc.perform(post("/api/incidents/{k}/takeover", incidentKey)
                        .header("X-Actor-Id", actor)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"commandKey\":\"" + key() + "\"}"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("COMMANDING"))
                .andExpect(jsonPath("$.commander").value(actor));
    }

    @Test
    void apiMainFlow() throws Exception {
        report("INC-300");
        takeover("INC-300", "alice");

        mvc.perform(post("/api/incidents/{k}/actions", "INC-300")
                        .header("X-Actor-Id", "alice")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"commandKey\":\"" + key()
                                + "\",\"actionKey\":\"A1\",\"actionType\":\"NOTE\",\"note\":\"n\","
                                + "\"occurredAt\":\"2026-09-21T08:00:00Z\"}"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.actor").value("alice"));

        mvc.perform(post("/api/incidents/{k}/transfers", "INC-300")
                        .header("X-Actor-Id", "alice")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"commandKey\":\"" + key() + "\",\"toCommander\":\"bob\"}"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("PENDING"));

        mvc.perform(get("/api/incidents/{k}", "INC-300"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.pendingTransferTo").value("bob"));

        mvc.perform(post("/api/incidents/{k}/transfers/accept", "INC-300")
                        .header("X-Actor-Id", "bob")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"commandKey\":\"" + key() + "\"}"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.commander").value("bob"));

        mvc.perform(get("/api/incidents/{k}/history", "INC-300"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.actions.length()").value(1))
                .andExpect(jsonPath("$.transfers.length()").value(1))
                .andExpect(jsonPath("$.transfers[0].status").value("ACCEPTED"));
    }

    @Test
    void apiErrorSemantics() throws Exception {
        // 400：缺 X-Actor-Id
        mvc.perform(post("/api/incidents/{k}/takeover", "INC-301")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"commandKey\":\"" + key() + "\"}"))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.code").value("BAD_REQUEST"));
        // 400：请求体非法 JSON
        mvc.perform(post("/api/incidents")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("not-json"))
                .andExpect(status().isBadRequest());
        // 400：参数非法
        mvc.perform(post("/api/incidents")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"incidentKey\":\"INC-302\",\"severity\":\"S9\","
                                + "\"summary\":\"s\",\"reporter\":\"r\"}"))
                .andExpect(status().isBadRequest());
        // 404：事件不存在
        mvc.perform(get("/api/incidents/{k}", "INC-404"))
                .andExpect(status().isNotFound())
                .andExpect(jsonPath("$.code").value("NOT_FOUND"));
        // 409：权限冲突（非当前指挥人）
        report("INC-303");
        takeover("INC-303", "alice");
        mvc.perform(post("/api/incidents/{k}/status", "INC-303")
                        .header("X-Actor-Id", "bob")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"commandKey\":\"" + key() + "\",\"targetStatus\":\"CONTAINED\"}"))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.code").value("CONFLICT"));
        // 422：非法流转（COMMANDING 直接 RESOLVED）
        mvc.perform(post("/api/incidents/{k}/status", "INC-303")
                        .header("X-Actor-Id", "alice")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"commandKey\":\"" + key() + "\",\"targetStatus\":\"RESOLVED\"}"))
                .andExpect(status().isUnprocessableEntity())
                .andExpect(jsonPath("$.code").value("ILLEGAL_TRANSITION"));
    }

    @Test
    void apiIdempotentReplay() throws Exception {
        report("INC-310");
        String commandKey = key();
        String body = "{\"commandKey\":\"" + commandKey + "\"}";
        String first = mvc.perform(post("/api/incidents/{k}/takeover", "INC-310")
                        .header("X-Actor-Id", "alice")
                        .contentType(MediaType.APPLICATION_JSON).content(body))
                .andExpect(status().isOk()).andReturn().getResponse().getContentAsString();
        // 同键同参重放：返回首次结果
        mvc.perform(post("/api/incidents/{k}/takeover", "INC-310")
                        .header("X-Actor-Id", "alice")
                        .contentType(MediaType.APPLICATION_JSON).content(body))
                .andExpect(status().isOk())
                .andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers
                        .content().json(first));
        // 同键改参：409
        mvc.perform(post("/api/incidents/{k}/takeover", "INC-310")
                        .header("X-Actor-Id", "mallory")
                        .contentType(MediaType.APPLICATION_JSON).content(body))
                .andExpect(status().isConflict());
    }
}

package com.example.starter.incident;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import java.time.Clock;
import java.time.Instant;
import java.util.UUID;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.context.annotation.Import;
import org.springframework.http.MediaType;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.web.servlet.MockMvc;

/**
 * 遏制逾期升级 HTTP 层测试：验证新路由、X-Actor-Id 约束、JSON 结构及
 * 400/404/409 错误语义；时间推进使用可控 Clock。
 */
@SpringBootTest
@AutoConfigureMockMvc
@Import(ControllableClock.Config.class)
class EscalationApiTest {

    private static final Instant T0 = Instant.parse("2026-09-22T00:00:00Z");

    @Autowired
    private MockMvc mvc;

    @Autowired
    private JdbcTemplate jdbc;

    @Autowired
    private Clock clock;

    @BeforeEach
    void clean() {
        jdbc.update("DELETE FROM command_keys");
        jdbc.update("DELETE FROM incident_escalations");
        jdbc.update("DELETE FROM incident_status_history");
        jdbc.update("DELETE FROM incident_transfers");
        jdbc.update("DELETE FROM incident_actions");
        jdbc.update("DELETE FROM incidents");
        ((ControllableClock) clock).setInstant(T0);
    }

    private static String key() {
        return "CMD-" + UUID.randomUUID();
    }

    @Test
    void escalationHttpFlow() throws Exception {
        mvc.perform(post("/api/incidents")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"incidentKey\":\"INC-H-1\",\"severity\":\"S1\",\"summary\":\"s\","
                                + "\"reporter\":\"r\"}"))
                .andExpect(status().isCreated());
        mvc.perform(post("/api/incidents/{k}/takeover", "INC-H-1")
                        .header("X-Actor-Id", "alice")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"commandKey\":\"" + key() + "\"}"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.deadlineAt").value("2026-09-22T00:05:00Z"));

        // 期限前检查：无记录
        mvc.perform(post("/api/incidents/{k}/escalations/check", "INC-H-1")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"commandKey\":\"" + key() + "\"}"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.current").value(org.hamcrest.Matchers.nullValue()))
                .andExpect(jsonPath("$.history.length()").value(0));

        // 只读查询不隐式写入
        mvc.perform(get("/api/incidents/{k}/escalations", "INC-H-1"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.deadlineAt").value("2026-09-22T00:05:00Z"))
                .andExpect(jsonPath("$.current").value(org.hamcrest.Matchers.nullValue()));

        // 越过期限后检查：OPEN
        ((ControllableClock) clock).setInstant(Instant.parse("2026-09-22T00:06:00Z"));
        mvc.perform(post("/api/incidents/{k}/escalations/check", "INC-H-1")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"commandKey\":\"" + key() + "\"}"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.current.status").value("OPEN"))
                .andExpect(jsonPath("$.current.triggeredCommander").value("alice"))
                .andExpect(jsonPath("$.history.length()").value(1));

        // 非指挥人确认 → 409；缺 X-Actor-Id → 400；空说明 → 400
        mvc.perform(post("/api/incidents/{k}/escalations/acknowledge", "INC-H-1")
                        .header("X-Actor-Id", "bob")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"commandKey\":\"" + key() + "\",\"note\":\"x\"}"))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.code").value("CONFLICT"));
        mvc.perform(post("/api/incidents/{k}/escalations/acknowledge", "INC-H-1")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"commandKey\":\"" + key() + "\",\"note\":\"x\"}"))
                .andExpect(status().isBadRequest());
        mvc.perform(post("/api/incidents/{k}/escalations/acknowledge", "INC-H-1")
                        .header("X-Actor-Id", "alice")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"commandKey\":\"" + key() + "\",\"note\":\"  \"}"))
                .andExpect(status().isBadRequest());

        // 当前指挥人确认成功；历史接口包含升级记录
        mvc.perform(post("/api/incidents/{k}/escalations/acknowledge", "INC-H-1")
                        .header("X-Actor-Id", "alice")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"commandKey\":\"" + key() + "\",\"note\":\"已接手处理\"}"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("ACKNOWLEDGED"))
                .andExpect(jsonPath("$.acknowledgedBy").value("alice"));
        mvc.perform(get("/api/incidents/{k}/history", "INC-H-1"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.escalations.length()").value(1))
                .andExpect(jsonPath("$.escalations[0].status").value("ACKNOWLEDGED"));
    }

    @Test
    void escalationHttpIdempotencyAndErrors() throws Exception {
        mvc.perform(post("/api/incidents")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"incidentKey\":\"INC-H-2\",\"severity\":\"S2\",\"summary\":\"s\","
                                + "\"reporter\":\"r\"}"))
                .andExpect(status().isCreated());
        mvc.perform(post("/api/incidents/{k}/takeover", "INC-H-2")
                        .header("X-Actor-Id", "alice")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"commandKey\":\"" + key() + "\"}"))
                .andExpect(status().isOk());
        ((ControllableClock) clock).setInstant(Instant.parse("2026-09-22T01:00:00Z"));

        String checkKey = key();
        String body = "{\"commandKey\":\"" + checkKey + "\"}";
        String first = mvc.perform(post("/api/incidents/{k}/escalations/check", "INC-H-2")
                        .contentType(MediaType.APPLICATION_JSON).content(body))
                .andExpect(status().isOk()).andReturn().getResponse().getContentAsString();
        mvc.perform(post("/api/incidents/{k}/escalations/check", "INC-H-2")
                        .contentType(MediaType.APPLICATION_JSON).content(body))
                .andExpect(status().isOk())
                .andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers
                        .content().json(first));

        // 缺 commandKey → 400
        mvc.perform(post("/api/incidents/{k}/escalations/check", "INC-H-2")
                        .contentType(MediaType.APPLICATION_JSON).content("{}"))
                .andExpect(status().isBadRequest());
        // 不存在 → 404
        mvc.perform(get("/api/incidents/{k}/escalations", "INC-404"))
                .andExpect(status().isNotFound());
        mvc.perform(post("/api/incidents/{k}/escalations/check", "INC-404")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"commandKey\":\"" + key() + "\"}"))
                .andExpect(status().isNotFound());
        // 遏制后检查不再新增，且 OPEN 记录被取消
        String ackKey = key();
        mvc.perform(post("/api/incidents/{k}/escalations/acknowledge", "INC-H-2")
                        .header("X-Actor-Id", "alice")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"commandKey\":\"" + ackKey + "\",\"note\":\"处理中\"}"))
                .andExpect(status().isOk());
        // 同键重放确认 → 首次结果；同键改 note → 409
        mvc.perform(post("/api/incidents/{k}/escalations/acknowledge", "INC-H-2")
                        .header("X-Actor-Id", "alice")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"commandKey\":\"" + ackKey + "\",\"note\":\"处理中\"}"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("ACKNOWLEDGED"));
        mvc.perform(post("/api/incidents/{k}/escalations/acknowledge", "INC-H-2")
                        .header("X-Actor-Id", "alice")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"commandKey\":\"" + ackKey + "\",\"note\":\"改了\"}"))
                .andExpect(status().isConflict());
    }
}

